#include <assert.h>
#include <stdio.h>
#include <sys/mman.h>
#include <sys/resource.h>
#include <unistd.h>

#ifndef MAP_ANONYMOUS
#define MAP_ANONYMOUS MAP_ANON
#endif

int main(void) {
    long page_size = sysconf(_SC_PAGESIZE);
    assert(page_size > 0);

    /* 分配 4 个页面的匿名私有映射，此时只建 VMA，不分配物理页 */
    size_t length = (size_t)page_size * 4;
    char *region = mmap(NULL, length, PROT_READ | PROT_WRITE,
                        MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (region == MAP_FAILED) {
        perror("mmap");
        return 1;
    }

    struct rusage before, after;
    assert(getrusage(RUSAGE_SELF, &before) == 0);

    /* 按页写入：每个虚拟页首次写入触发 minor fault（匿名零页分配） */
    for (size_t off = 0; off < length; off += (size_t)page_size) {
        region[off] = (char)(off / (size_t)page_size + 1);
    }

    assert(getrusage(RUSAGE_SELF, &after) == 0);

    printf("page size: %ld\n", page_size);
    printf("mapped bytes: %zu\n", length);
    printf("first page marker: %d\n", region[0]);
    printf("last page marker: %d\n", region[3 * (size_t)page_size]);
    printf("minor faults delta: %ld\n", after.ru_minflt - before.ru_minflt);
    printf("major faults delta: %ld\n", after.ru_majflt - before.ru_majflt);

    assert(region[0] == 1);
    assert(region[3 * (size_t)page_size] == 4);
    assert(munmap(region, length) == 0);
    return 0;
}
